const wallMat = new THREE.ShaderMaterial({
  vertexShader: `
    varying vec3 roomPosition;
    void main(){
      roomPosition = (modelMatrix * vec4(position,1.0)).xyz;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0);
    }
  `,
  fragmentShader: `
    varying vec3 roomPosition;
    ${noiseGLSL}
    void main(){
      vec2 p = vec2(roomPosition.x+120.0,
        121.0-(${co.toFixed(7)}*roomPosition.y-${si.toFixed(7)}*roomPosition.z));
      float smallGrain = nwbNoise(vec3(p*0.73,3.0));
      float broadGrain = nwbNoise(vec3(p*0.049,8.0));
      vec3 color = mix(${colorCode(0xb8a99a)},${colorCode(0xa5a8ab)},
        smoothstep(12.0,223.0,p.x)*0.96);
      color *= 0.96+0.072*broadGrain+0.035*smallGrain;
      float lowerEdge = 36.7-0.028*(p.x-72.0);
      float shadow = smoothstep(59.0,75.0,p.x)*(1.0-smoothstep(lowerEdge,lowerEdge+6.0,p.y));
      color *= 1.0-0.29*shadow;
      float frame = smoothstep(66.0,75.5,p.x)
        *(1.0-smoothstep(lowerEdge-2.0,lowerEdge+2.8,p.y));
      color = mix(color,${colorCode(0x615245)}*(0.94+0.10*broadGrain),frame);
      float board = smoothstep(72.0,80.0,p.x)
        *(1.0-smoothstep(lowerEdge-8.3,lowerEdge-3.8,p.y));
      vec3 chalk = mix(${colorCode(0x12282e)},${colorCode(0x203d42)},
        smoothstep(60.0,248.0,p.x)*0.87);
      chalk *= 0.87+0.21*broadGrain+0.05*smallGrain;
      color = mix(color,chalk,board);
      float eraser = exp(-pow((p.x-114.0)/17.0,2.0)-pow((p.y-31.3)/2.3,2.0));
      color = mix(color,${colorCode(0x8c7961)},eraser*0.71);
      float rail = smoothstep(77.0,85.0,p.y)*(1.0-smoothstep(89.0,101.0,p.y));
      color = mix(color,${colorCode(0x8d745b)},rail*(0.65+0.12*broadGrain));
      gl_FragColor = vec4(color,1.0);
      #include <colorspace_fragment>
    }
  `
});
